struct Shared { sem_t lock; long counter; };

int fd = shm_open("/cnt", O_CREAT | O_RDWR, 0600);
ftruncate(fd, sizeof(Shared));
auto* s = static_cast<Shared*>(mmap(nullptr, sizeof(Shared),
    PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0));
sem_init(&s->lock, 0, 1);

pid_t pid = fork();
for (int i = 0; i < 1000000; ++i) {
    sem_wait(&s->lock);
    s->counter++;
    sem_post(&s->lock);
}

